def interpret(evidence):
    asset = evidence["asset"]
    classes = {c["id"]: c for c in evidence["classes"]}
    findings, steps = [], []
    for i, cid in enumerate(sorted(classes), start=1):
        c = classes[cid]
        findings.append({"id": f"F{i}", "statement": f"{c['label']} cells cover {c['share_pct']}% of the grid ({c['cell_count']} cells).",
                         "evidence": [f"class:{cid}"]})
    summary = f"{asset['label']}: each cell is labelled with its most frequent surface class."
    steps.append({"type": "human_inspection",
                  "description": "Check a sample of cells from each class against the source image to judge the rule-based labels.",
                  "follows_from": findings[0]["id"]})
    return {"summary": summary, "findings": findings, "next_steps": steps}
